//! Bounded one-action input IPC. Installed native owner/foreground authority is
//! required; no client flag, environment variable or API key substitutes for it.
use serde::Deserialize;
#[path="computer_input_authority.rs"] mod authority;
use tauri::Manager;
use std::sync::atomic::{AtomicU64,Ordering};
static INPUT_GENERATION:AtomicU64=AtomicU64::new(0);
#[no_mangle]pub extern "C" fn axiom_input_generation()->u64{INPUT_GENERATION.load(Ordering::SeqCst)}
use serde_json::{json,Value};
