const MAX_REPLY:usize=24576;
#[derive(Debug,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct StatusInput{task_id:String,task_version:u32}
#[derive(Debug,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct PrepareInput {owner_context_ref:String,task_id:String,task_version:u32,observation_session_id:String,observation_revision:u32,text:String}
#[derive(Debug,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct ConfirmInput {owner_context_ref:String,task_id:String,task_version:u32,input_session_id:String,action_id:String,expected_revision:u32}
#[derive(Debug,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct StopInput {owner_context_ref:String,input_session_id:Option<String>}
#[derive(Debug,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct RecoverInput {owner_context_ref:String,task_id:String,task_version:u32,action_id:String}
fn identity(s:&str)->bool {!s.is_empty()&&s.len()<=240&&s.trim()==s&&!s.chars().any(char::is_control)}
fn named_uuid(s:&str,prefix:&str)->bool {let Some(id)=s.strip_prefix(prefix)else{return false};id.len()==36&&id.bytes().enumerate().all(|(i,b)|if [8,13,18,23].contains(&i){b==b'-'}else{b.is_ascii_digit()||(b'a'..=b'f').contains(&b)})}
fn text(s:&str)->bool {s.len()<=4096&&!s.chars().any(|c|c=='\0'||c.is_control()&&c!='\n'&&c!='\t')}
#[cfg(any(target_os="macos",test))]
fn digest(v:&Value)->bool {v.as_str().map(|s|s.len()==64&&s.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b))).unwrap_or(false)}
#[cfg(any(target_os="macos",test))]
fn time(v:&Value)->bool {v.as_str().and_then(|s|chrono::DateTime::parse_from_rfc3339(s).ok().map(|d|d.to_rfc3339_opts(chrono::SecondsFormat::Millis,true)==s)).unwrap_or(false)}
fn exact(v:&Value,keys:&[&str])->bool {v.as_object().map(|o|o.len()==keys.len()&&keys.iter().all(|k|o.contains_key(*k))).unwrap_or(false)}
fn fixed(v:&Value)->bool {v["source"]=="native_selected_window_input"}
fn status(v:&Value)->bool {exact(v,&["source","supported","inputAvailable","typeAvailable","pressAvailable","ownerAuthorityAvailable","foregroundPolicyAvailable","reason","aiSharingAvailable","backgroundInput"])&&fixed(v)&&["supported","inputAvailable","typeAvailable","ownerAuthorityAvailable","foregroundPolicyAvailable"].iter().all(|k|v[*k].is_boolean())&&v["pressAvailable"]==false&&v["aiSharingAvailable"]==false&&v["backgroundInput"]==false&&(v["inputAvailable"]!=true||v["supported"]==true&&v["typeAvailable"]==true&&v["ownerAuthorityAvailable"]==true&&v["foregroundPolicyAvailable"]==true)&&["owner_authority_unavailable","owner_credential_unavailable","owner_service_unavailable","owner_service_refused","owner_proof_invalid","owner_proof_time_invalid","owner_proof_binding_invalid","owner_proof_native_rejected","accessibility_unavailable","ready","os_unsupported"].iter().any(|s|v["reason"]==*s)&&(!["owner_credential_unavailable","owner_service_unavailable","owner_service_refused","owner_proof_invalid","owner_proof_time_invalid","owner_proof_binding_invalid","owner_proof_native_rejected"].iter().any(|s|v["reason"]==*s)||v["inputAvailable"]==false&&v["typeAvailable"]==false&&v["ownerAuthorityAvailable"]==false)}
#[cfg(any(target_os="macos",test))]
fn result(v:&Value,input:&Value)->bool {let status=v["status"].as_str().unwrap_or("");let attempt=v["attemptCount"].as_u64();exact(v,&["source","inputSessionId","actionId","revision","status","attemptCount","beforeDigest","afterDigest","targetDigest","expiresAt","inputPerformed"])&&fixed(v)&&v["inputSessionId"].as_str().map(|s|named_uuid(s,"input_session_")).unwrap_or(false)&&v["actionId"]==input["actionId"]&&v["actionId"].as_str().map(|s|named_uuid(s,"input_action_")).unwrap_or(false)&&v["revision"].as_u64().map(|n|n<=2147483647).unwrap_or(false)&&["confirmed","refused","unknown","stopped","expired"].contains(&status)&&matches!(attempt,Some(0)|Some(1))&&["beforeDigest","afterDigest","targetDigest"].iter().all(|k|digest(&v[*k]))&&time(&v["expiresAt"])&&match status{"confirmed"=>attempt==Some(1)&&v["inputPerformed"]==true,"unknown"=>attempt==Some(1)&&v["inputPerformed"].is_null(),_=>v["inputPerformed"]==false}}
#[cfg(any(target_os="macos",test))]
fn checked(op:i32,v:Value,input:&Value)->Result<Value,String>{let good=match op{0=>status(&v),1=>exact(&v,&["source","kind","inputSessionId","actionId","revision","taskId","taskVersion","targetLabel","beforeText","afterText","beforeDigest","afterDigest","targetDigest","expiresAt","attemptCount"])&&fixed(&v)&&v["kind"]=="set_text"&&v["inputSessionId"].as_str().map(|s|named_uuid(s,"input_session_")).unwrap_or(false)&&v["actionId"].as_str().map(|s|named_uuid(s,"input_action_")).unwrap_or(false)&&v["revision"]==0&&v["attemptCount"]==0&&v["taskId"]==input["taskId"]&&v["taskVersion"]==input["taskVersion"]&&v["targetLabel"].as_str().map(identity).unwrap_or(false)&&v["beforeText"].as_str().map(text).unwrap_or(false)&&v["afterText"]==input["text"]&&["beforeDigest","afterDigest","targetDigest"].iter().all(|k|digest(&v[*k]))&&time(&v["expiresAt"]),2|4=>result(&v,input),3=>exact(&v,&["stopped"])&&v["stopped"]==true,_=>false};if good{Ok(v)}else{Err("native_input_invalid_response".into())}}
#[cfg(any(target_os="macos",test))]
fn allowed_error(s:&str)->bool {["native_input_invalid_request","native_input_invalid_response","native_input_unsupported","native_input_unavailable","native_input_owner_authority_unavailable","native_input_foreground_policy_unavailable","native_input_accessibility_unavailable","native_input_target_unavailable","native_input_busy","native_input_foreground_required","native_input_target_identity_unavailable","native_input_window_inventory_unavailable","native_input_text_structure_unavailable","native_input_text_not_editable","native_input_tree_incomplete","native_input_text_area_count","native_input_secure_text_area","native_input_text_enabled_unverified","native_input_text_disabled","native_input_text_value_unavailable","native_input_text_size_limit","native_input_saved_document","native_input_fixture_mismatch","native_input_ambiguous_window","native_input_session_changed","native_input_expired","native_input_stopped","native_input_outcome_unknown"].contains(&s)}
