mod native {
 use super::*;use std::{collections::HashMap,ffi::{CStr,CString,c_char},sync::{Mutex,OnceLock,atomic::{AtomicU64,Ordering}}};use tokio::sync::oneshot;
 static NEXT:AtomicU64=AtomicU64::new(1);type Sender=oneshot::Sender<Result<Value,String>>;static REQUESTS:OnceLock<Mutex<HashMap<u64,Sender>>>=OnceLock::new();
 fn requests()->&'static Mutex<HashMap<u64,Sender>>{REQUESTS.get_or_init(||Mutex::new(HashMap::new()))}
 extern "C"{fn axiom_input_request(op:i32,id:u64,input:*const c_char,callback:extern "C" fn(u64,*const c_char));}
 extern "C" fn reply(id:u64,raw:*const c_char){let sender=requests().lock().ok().and_then(|mut m|m.remove(&id));let Some(sender)=sender else{return};let result=if raw.is_null(){Err("native_input_unavailable".into())}else{let bytes=unsafe{CStr::from_ptr(raw)}.to_bytes();if bytes.len()>MAX_REPLY{Err("native_input_invalid_response".into())}else{match serde_json::from_slice::<Value>(bytes){Ok(v)if exact(&v,&["ok","data"])&&v["ok"]==true=>Ok(v["data"].clone()),Ok(v)if exact(&v,&["ok","error"])&&v["ok"]==false&&v["error"].as_str().map(allowed_error).unwrap_or(false)=>Err(v["error"].as_str().unwrap().to_owned()),_=>Err("native_input_invalid_response".into())}}};let _=sender.send(result);}
 extern "C" fn ignored(_:u64,_:*const c_char){}
 fn dispatch(op:i32,id:u64,input:&Value,callback:extern "C" fn(u64,*const c_char))->Result<(),String>{let s=serde_json::to_string(input).map_err(|_|"native_input_invalid_request")?;if s.len()>12288{return Err("native_input_invalid_request".into())}let s=CString::new(s).map_err(|_|"native_input_invalid_request")?;unsafe{axiom_input_request(op,id,s.as_ptr(),callback)};Ok(())}
 struct Pending(u64);impl Drop for Pending{fn drop(&mut self){if let Ok(mut m)=requests().lock(){m.remove(&self.0);}}}
 pub async fn request(op:i32,input:Value)->Result<Value,String>{let id=NEXT.fetch_add(1,Ordering::Relaxed);let(tx,rx)=oneshot::channel();{let mut m=requests().lock().map_err(|_|"native_input_unavailable")?;if m.len()>=8{return Err("native_input_unavailable".into())}m.insert(id,tx);}let _pending=Pending(id);dispatch(op,id,&input,reply)?;match tokio::time::timeout(std::time::Duration::from_secs(if op==2{60}else{12}),rx).await{Ok(Ok(result))=>result,_=>{let cancel=json!({"ownerContextRef":input["ownerContextRef"],"inputSessionId":input.get("inputSessionId").cloned().unwrap_or(Value::Null)});let _=dispatch(3,0,&cancel,ignored);Err(if op==2{"native_input_outcome_unknown"}else{"native_input_unavailable"}.into())}}}
 pub fn cancel(input:&Value){let _=dispatch(3,0,&json!({"ownerContextRef":input["ownerContextRef"],"inputSessionId":input["inputSessionId"]}),ignored);}
 pub fn revoke_all(){let _=dispatch(5,0,&json!({}),ignored);}
}
async fn request(op:i32,input:Value)->Result<Value,String>{#[cfg(target_os="macos")]{let v=native::request(op,input.clone()).await?;checked(op,v,&input)}#[cfg(not(target_os="macos"))]{let _=input;if op==0{Ok(json!({"source":"native_selected_window_input","supported":false,"inputAvailable":false,"typeAvailable":false,"pressAvailable":false,"ownerAuthorityAvailable":false,"foregroundPolicyAvailable":false,"reason":"os_unsupported","aiSharingAvailable":false,"backgroundInput":false}))}else{Err("native_input_unsupported".into())}}}
fn main(window:&tauri::WebviewWindow)->Result<(),String>{if window.label()=="main"{Ok(())}else{Err("native_input_invalid_request".into())}}
fn status_failure(mut v:Value,error:&str)->Result<Value,String>{if !status(&v){return Err("native_input_invalid_response".into())}
 if v["supported"]==true{v["inputAvailable"]=json!(false);v["typeAvailable"]=json!(false);v["ownerAuthorityAvailable"]=json!(false);v["reason"]=json!(match error{"owner_credential_unavailable"=>"owner_credential_unavailable","owner_service_unavailable"=>"owner_service_unavailable","owner_service_refused"=>"owner_service_refused","owner_proof_invalid"=>"owner_proof_invalid","owner_proof_time_invalid"=>"owner_proof_time_invalid","owner_proof_binding_invalid"=>"owner_proof_binding_invalid","owner_proof_native_rejected"=>"owner_proof_native_rejected",_=>"owner_authority_unavailable"})}
 if status(&v){Ok(v)}else{Err("native_input_invalid_response".into())}}
#[tauri::command]pub async fn computer_input_status(app:tauri::AppHandle,window:tauri::WebviewWindow,input:Option<StatusInput>)->Result<Value,String>{main(&window)?;let attestation=if let Some(i)=input{authority::attest(&app,&i.task_id,i.task_version).await}else{Err("owner_credential_unavailable".into())};match attestation{Ok(value)=>{let v=request(0,json!({"authority":value})).await?;if v["supported"]==true&&v["ownerAuthorityAvailable"]==false&&v["reason"]=="owner_authority_unavailable"{status_failure(v,"owner_proof_native_rejected")}else{Ok(v)}},Err(error)=>status_failure(request(0,json!({"authority":Value::Null})).await?,&error)}}
#[tauri::command]pub async fn computer_input_prepare(app:tauri::AppHandle,window:tauri::WebviewWindow,input:PrepareInput)->Result<Value,String>{main(&window)?;let generation=INPUT_GENERATION.load(Ordering::SeqCst);if !identity(&input.owner_context_ref)||!identity(&input.task_id)||input.task_version>2147483647||!named_uuid(&input.observation_session_id,"observation_")||input.observation_revision>2147483647||!text(&input.text){return Err("native_input_invalid_request".into())}let attestation=authority::attest(&app,&input.task_id,input.task_version).await.map_err(|_|"native_input_owner_authority_unavailable")?;if generation!=INPUT_GENERATION.load(Ordering::SeqCst){return Err("native_input_stopped".into())}let directory=app.path().app_data_dir().map_err(|_|"native_input_unavailable")?.join("computer-input-ledger");request(1,json!({"authority":attestation,"nativeGeneration":generation,"ledgerDirectory":directory.to_string_lossy(),"ownerContextRef":input.owner_context_ref,"taskId":input.task_id,"taskVersion":input.task_version,"observationSessionId":input.observation_session_id,"observationRevision":input.observation_revision,"text":input.text})).await}
#[tauri::command]pub async fn computer_input_confirm(app:tauri::AppHandle,window:tauri::WebviewWindow,input:ConfirmInput)->Result<Value,String>{main(&window)?;let generation=INPUT_GENERATION.load(Ordering::SeqCst);if !identity(&input.owner_context_ref)||!identity(&input.task_id)||input.task_version>2147483647||!named_uuid(&input.input_session_id,"input_session_")||!named_uuid(&input.action_id,"input_action_")||input.expected_revision>2147483647{return Err("native_input_invalid_request".into())}let attestation=authority::attest(&app,&input.task_id,input.task_version).await.map_err(|_|"native_input_owner_authority_unavailable")?;if generation!=INPUT_GENERATION.load(Ordering::SeqCst){return Err("native_input_stopped".into())}let directory=app.path().app_data_dir().map_err(|_|"native_input_unavailable")?.join("computer-input-ledger");let original=json!({"authority":attestation,"nativeGeneration":generation,"ledgerDirectory":directory.to_string_lossy(),"ownerContextRef":input.owner_context_ref,"taskId":input.task_id,"taskVersion":input.task_version,"inputSessionId":input.input_session_id,"actionId":input.action_id,"expectedRevision":input.expected_revision});
 #[cfg(target_os="macos")]{let first=native::request(2,original.clone()).await?;if !exact(&first,&["source","handoffReady","inputSessionId","actionId","handoffNonce"])||first["source"]!="native_selected_window_input"||first["handoffReady"]!=true||first["inputSessionId"]!=original["inputSessionId"]||first["actionId"]!=original["actionId"]||!first["handoffNonce"].as_str().map(|s|named_uuid(s,"")).unwrap_or(false){return checked(2,first,&original)}let refreshed=match authority::attest(&app,&input.task_id,input.task_version).await{Ok(a)=>a,Err(_)=>{native::cancel(&original);return Err("native_input_owner_authority_unavailable".into())}};if generation!=INPUT_GENERATION.load(Ordering::SeqCst){native::cancel(&original);return Err("native_input_stopped".into())}let mut continuation=original.clone();continuation["authority"]=refreshed;continuation["handoffNonce"]=first["handoffNonce"].clone();let final_result=native::request(6,continuation).await;match final_result{Ok(v)=>checked(2,v,&original),Err(e)=>{native::cancel(&original);Err(e)}}}
 #[cfg(not(target_os="macos"))]{let _=original;Err("native_input_unsupported".into())}
}
#[tauri::command]pub async fn computer_input_stop(window:tauri::WebviewWindow,input:StopInput)->Result<Value,String>{main(&window)?;INPUT_GENERATION.fetch_add(1,Ordering::SeqCst);if !identity(&input.owner_context_ref)||input.input_session_id.as_ref().map(|s|!named_uuid(s,"input_session_")).unwrap_or(false){return Err("native_input_invalid_request".into())}request(3,json!({"ownerContextRef":input.owner_context_ref,"inputSessionId":input.input_session_id})).await}
#[tauri::command]pub async fn computer_input_recover(app:tauri::AppHandle,window:tauri::WebviewWindow,input:RecoverInput)->Result<Value,String>{main(&window)?;if !identity(&input.owner_context_ref)||!identity(&input.task_id)||input.task_version>2147483647||!named_uuid(&input.action_id,"input_action_"){return Err("native_input_invalid_request".into())}let attestation=authority::attest(&app,&input.task_id,input.task_version).await.map_err(|_|"native_input_owner_authority_unavailable")?;let directory=app.path().app_data_dir().map_err(|_|"native_input_unavailable")?.join("computer-input-ledger");request(4,json!({"authority":attestation,"ledgerDirectory":directory.to_string_lossy(),"ownerContextRef":input.owner_context_ref,"taskId":input.task_id,"taskVersion":input.task_version,"actionId":input.action_id})).await}
pub fn revoke_all(){INPUT_GENERATION.fetch_add(1,Ordering::SeqCst);#[cfg(target_os="macos")]native::revoke_all();}
#[cfg(test)]mod tests{use super::*;
 #[test]fn confirmation_boolean_and_native_target_ids_are_never_authority(){let good=json!({"ownerContextRef":"owned","taskId":"task","taskVersion":1,"inputSessionId":"input_session_11111111-1111-4111-8111-111111111111","actionId":"input_action_11111111-1111-4111-8111-111111111111","expectedRevision":0});assert!(serde_json::from_value::<ConfirmInput>(good.clone()).is_ok());for key in ["confirm","approved","pid","windowId","apiKey"]{let mut v=good.clone();v[key]=json!(true);assert!(serde_json::from_value::<ConfirmInput>(v).is_err());}}
 #[test]fn text_and_identity_utf8_bounds_are_exact(){assert!(text(&"é".repeat(2048)));assert!(!text(&"é".repeat(2049)));assert!(!text("password\0"));assert!(identity("opaque-owner"));assert!(!identity(" bad"));assert!(!named_uuid("input_action_11111111-1111-4111-8111-111111111111/else","input_action_"));}
 #[test]fn missing_native_authority_never_advertises_input_or_press(){let mut v=json!({"source":"native_selected_window_input","supported":true,"inputAvailable":false,"typeAvailable":false,"pressAvailable":false,"ownerAuthorityAvailable":false,"foregroundPolicyAvailable":false,"reason":"owner_authority_unavailable","aiSharingAvailable":false,"backgroundInput":false});assert!(checked(0,v.clone(),&json!({})).is_ok());for key in ["inputAvailable","pressAvailable","aiSharingAvailable","backgroundInput"]{v[key]=json!(true);assert!(checked(0,v.clone(),&json!({})).is_err());v[key]=json!(false);}}
}

#[cfg(test)]mod diagnostic_tests{use super::*;#[test]fn only_fixed_stages_leave_status_and_never_enable_input(){let v=json!({"source":"native_selected_window_input","supported":true,"inputAvailable":false,"typeAvailable":false,"pressAvailable":false,"ownerAuthorityAvailable":false,"foregroundPolicyAvailable":true,"reason":"owner_authority_unavailable","aiSharingAvailable":false,"backgroundInput":false});for stage in ["owner_credential_unavailable","owner_service_unavailable","owner_service_refused","owner_proof_invalid","owner_proof_time_invalid","owner_proof_binding_invalid","owner_proof_native_rejected"]{let out=status_failure(v.clone(),stage).unwrap();assert_eq!(out["reason"],stage);assert_eq!(out["inputAvailable"],false);assert_eq!(out["ownerAuthorityAvailable"],false)}let out=status_failure(v,"secret body id arbitrary").unwrap();assert_eq!(out["reason"],"owner_authority_unavailable");assert!(!out.to_string().contains("secret"));}}

#[cfg(test)] mod saved_document_diagnostic_tests { use super::*; #[test] fn only_fixed_saved_document_error_crosses_bridge() { assert!(allowed_error("native_input_saved_document")); assert!(allowed_error("native_input_fixture_mismatch")); assert!(!allowed_error("native_input_fixture_mismatch: private file")); assert!(!allowed_error("native_input_saved_document: private file")); } }
